from course_model import *
c=chapter('node','Node · fișiere și aplicații','Terminal, module, callback-uri, căi, fișiere și organizarea serverului.','[lamuriri suplimentare] Node și Express - introducere.pptx, 3–32; index.js','terminal')
def N(id,title,idea,body,cases,question,prompt,files=None,example=None):
 code=body if 'function solve' in body else 'function solve(input) {\n  '+body.replace('\n','\n  ')+'\n}'
 task=js(prompt,code,cases,mode='node',files=files or {})
 lesson(c,id,title,idea,example or code,idea,question,task)
lesson(c,'node-run','Rulează un fișier din terminal','Node execută JavaScript în afara browserului. Terminalul primește o comandă; apoi procesul rulează codul. console.log apare în terminal, nu într-un element HTML.',
 'node app.js','Nu există document în Node. În proiect, fișierul serverului este app.js.',q('Ce comandă pornește app.js cu Node?','node app.js','html app.js','npm css'),text('Scrie comanda care execută app.js.','node app.js'))
lesson(c,'node-npm','Pachete și npm','Un pachet este cod reutilizabil instalat în proiect. npm install express adaugă dependența Express. node_modules se poate reinstala din manifest și lockfile; nu îl copiezi în repository.',
 'npm install express\nnpm run start','Un script din package.json oferă un nume scurt pentru o comandă. Instalarea are nevoie de internet; rularea codului local nu implică automat publicarea site-ului.',q('Unde se declară dependențele?','package.json','index.html obligatoriu','În atributul src al fiecărui p'),text('Scrie comanda de instalare a Express.','npm install express'))
lesson(c,'node-package','Manifestul proiectului','package.json este JSON valid și poate conține name, version, scripts și dependencies. CommonJS folosește require și module.exports; modulele ES folosesc import și export.',
 '{\n  "name": "sweet-corner",\n  "scripts": { "start": "node app.js" }\n}', 'Manifestul proiectului final folosește CommonJS pentru a rămâne apropiat de exemplul profesoarei.',q('Ce fișier descrie scriptul start?','package.json','style.scss','captions.vtt'),dict(mode='json',prompt='Scrie un manifest cu name sweet-corner și scripts.start node app.js.',solution='{"name":"sweet-corner","scripts":{"start":"node app.js"}}',starter='{}',expected={'name':'sweet-corner','scripts':{'start':'node app.js'}}))
lesson(c,'node-event-loop','Callback și event loop','O operație asincronă poate anunța finalizarea prin callback. Event loop permite tratarea evenimentelor; nu înseamnă că orice calcul JavaScript rulează automat pe un alt fir.',
 'console.log("A");\nsetTimeout(() => console.log("B"), 0);\nconsole.log("C");', 'Codul sincron afișează A și C înaintea callback-ului B. Un calcul sincron lung poate bloca tratarea altor cereri.',q('Care este ordinea mesajelor?','A C B','A B C','B A C'),text('Scrie literele în ordinea afișării, separate prin spațiu.','A C B'))
N('node-require','Încarcă un modul','require încarcă un modul CommonJS. Module precum path sunt incluse în Node; Express este un pachet separat. Numele modulului este text.', 'const path = require("path");\nfunction solve(input) { return path.extname(input); }',[('image.webp','.webp'),('app.js','.js'),('README','')],q('Trebuie instalat path din npm pentru Node?','Nu, este inclus','Da, obligatoriu','Numai pentru HTML'),'Folosește path.extname pentru extensia căii input.')
N('node-join','Compune o cale','path.join compune segmente și normalizează separatori. O cale de pe disc nu este automat un URL. În laborator folosim path POSIX și rădăcina virtuală /project pentru rezultate stabile.', 'const path = require("path");\nfunction solve(input) { return path.join("/project", "public", input); }',[('cake.svg','/project/public/cake.svg'),('css/site.css','/project/public/css/site.css')],q('Ce compune path.join?','O cale','Un query SQL','Un template EJS'),'Returnează calea /project/public plus segmentul input.')
N('node-basename','Nume, extensie și director','path.basename extrage ultima componentă, dirname directorul, extname extensia. path.parse oferă aceste componente într-un obiect.', 'const path = require("path");\nfunction solve(input) { return { name: path.basename(input), extension: path.extname(input), folder: path.dirname(input) }; }',[('/project/images/cake.webp',{'name':'cake.webp','extension':'.webp','folder':'/project/images'})],q('Ce returnează basename?','Ultima componentă a căii','Întregul fișier citit','Portul HTTP'),'Returnează name, extension și folder pentru calea input.')
N('node-dirname','Directorul scriptului și directorul de lucru','__dirname este directorul modulului CommonJS. process.cwd() este directorul din care a fost pornit procesul. Folosește __dirname pentru resurse legate de fișierul aplicației.', 'function solve(input) { return __dirname; }',[(None,'/project')],q('Ce este __dirname?','Directorul modulului CommonJS','Domeniul web','Folderul browserului'),'Returnează __dirname din laboratorul virtual.')
N('node-read','Citește text cu fs','fs.readFileSync citește sincron. Argumentul utf8 cere text; fără el primești un Buffer. În laborator fs lucrează numai cu fișiere virtuale furnizate de exercițiu.', 'const fs = require("fs");\nfunction solve(input) { return fs.readFileSync("message.txt", "utf8"); }',[(None,'Welcome')],q('Ce argument cere text UTF-8?','"utf8"','true ca regulă generală','"html"'),'Citește fișierul virtual message.txt ca text.',{'message.txt':'Welcome'})
N('node-buffer','Buffer și codificare','Buffer reprezintă octeți. toString("utf8") îi transformă în text interpretat cu acea codificare. Nu confunda lungimea în octeți cu numărul vizual de caractere.', 'const fs = require("fs");\nfunction solve(input) { return fs.readFileSync("message.txt").toString("utf8"); }',[(None,'Cake')],q('Ce conține un Buffer?','Octeți','Elemente DOM','Rute Express'),'Citește Buffer-ul virtual și convertește-l în text.',{'message.txt':'Cake'})
N('node-json-file','Un fișier JSON devine date','Citirea și parsarea sunt două operații. fs oferă textul; JSON.parse verifică sintaxa și produce obiectul. Această structură este folosită pentru galerie și erori.', 'const fs = require("fs");\nfunction solve(input) { return JSON.parse(fs.readFileSync("data/gallery.json", "utf8")).images.length; }',[(None,2)],q('Ce transformă textul în obiect?','JSON.parse','readFileSync singur','path.join'),'Returnează numărul imaginilor din fișierul virtual.',{'data/gallery.json':'{"images":["cake.webp","tea.webp"]}'})
N('node-exists','Verifică existența','existsSync spune dacă o cale există în mediul de fișiere. În proiect se pot crea directoare de lucru doar când lipsesc; nu presupune că orice cale există pe alt calculator.', 'const fs = require("fs");\nfunction solve(input) { return fs.existsSync(input); }',[('data.json',True),('missing.json',False)],q('Ce tip returnează existsSync?','boolean','Conținutul fișierului','Un cod HTTP'),'Verifică existența căii input în fișierele virtuale.',{'data.json':'{}'})
N('node-write','Scrie într-un fișier virtual','writeFileSync creează sau înlocuiește conținutul. În laborator nu are acces la documentele tale; în proiectul real trebuie să alegi explicit folderul destinație.', 'const fs = require("fs");\nfunction solve(input) { fs.writeFileSync("result.txt", input); return fs.readFileSync("result.txt", "utf8"); }',[('Cake','Cake'),('Tea','Tea')],q('writeFileSync adaugă automat fără să înlocuiască?','Nu; în mod normal înlocuiește conținutul','Da, întotdeauna','Scrie doar în SQL'),'Scrie input în result.txt virtual și citește-l înapoi.')
N('node-async-read','Citire asincronă și await','O funcție async poate aștepta o promisiune cu await. fs.promises oferă metode care returnează promisiuni. await nu transformă orice calcul CPU într-un calcul paralel.', 'const fs = require("fs");\nasync function solve(input) { return await fs.promises.readFile("message.txt", "utf8"); }',[(None,'Async read')],q('Ce primește await pentru a aștepta o operație?','O promisiune sau o valoare','Un thread Windows obligatoriu','Un tag HTML'),'Citește asincron message.txt virtual.',{'message.txt':'Async read'})
N('node-crypto','Hash-uri cu crypto','crypto oferă funcții pentru prelucrarea criptografică. Un hash este un rezumat determinist, nu o criptare reversibilă. În proiectul de bază nu inventăm un sistem de autentificare dintr-un simplu hash.', 'const crypto = require("crypto");\nfunction solve(input) { return crypto.createHash("sha256").update(input).digest("hex").length; }',[('Cake',64),('',64)],q('Poți recupera direct textul prin decriptarea unui hash?','Nu; hash-ul nu este criptare reversibilă','Da, cu JSON.parse','Da, cu toString'),'Returnează lungimea în caractere a digestului SHA-256 hex.')
lesson(c,'node-watch','Supravegherea fișierelor și backup','fs.watch poate semnala modificări, iar aplicația poate recompila SCSS. Evenimentele pot apărea de mai multe ori și numele poate lipsi; verifică existența fișierului și extensia înainte de procesare.',
 'fs.watch(sourceFolder, (eventType, fileName) => {\n  if (fileName && path.extname(fileName) === ".scss") {\n    // Recompile a known source file.\n  }\n});', 'În proiect separăm sursele SCSS de CSS-ul generat și facem backup înainte de înlocuirea unui CSS existent. Nu tratăm fiecare eveniment ca o comandă sigură de ștergere.',q('Ce verifici înainte să compilezi numele primit?','Că există și este o sursă așteptată','Doar culoarea fișierului','Nimic, orice cale este bună'),text('Scrie extensia surselor pe care le compilăm.','.scss'))

c=chapter('express','Express · cereri și răspunsuri reale','Rute, middleware, parametri, resurse statice și erori HTTP.','Node și Express, 30–77; index.js din exemplu','server')
def X(id,title,idea,route,requests,quiz,extra='',prompt=None):
 code='const express = require("express");\nconst app = express();\n'+extra+'\n'+route+'\nmodule.exports = app;'
 lesson(c,id,title,idea,code,idea,quiz,express(prompt or 'Construiește aplicația din exemplu. Exportă app; laboratorul pornește temporar serverul pentru teste.',code,requests))
X('express-first','Prima aplicație Express','express() creează aplicația. app.get asociază o cale și o funcție pentru cereri GET. Exportăm app în laborator; app.listen apare în fișierul de pornire al proiectului.', 'app.get("/hello", (req, res) => { res.send("Hello"); });',[dict(path='/hello',bodyExpected='Hello')],q('Ce creează express()?','Aplicația','O bază de date','Un fișier CSS'))
X('express-method','Metoda HTTP contează','GET și POST pe aceeași cale pot avea handlers diferite. Faptul că există GET /message nu înseamnă că orice metodă pe /message este tratată.', 'app.get("/message", (req, res) => res.send("Read"));\napp.post("/message", (req, res) => res.send("Write"));',[dict(path='/message',bodyExpected='Read'),dict(path='/message',method='POST',bodyExpected='Write')],q('Sunt GET și POST aceeași metodă?','Nu','Da, dacă URL-ul coincide','Numai în Express'))
X('express-json','Răspuns JSON','res.json serializează datele și setează tipul de conținut potrivit. res.send poate trimite text sau HTML. Nu construi manual JSON prin concatenarea textelor.', 'app.get("/status", (req, res) => res.json({ ready: true }));',[dict(path='/status',json={'ready':True})],q('Ce metodă trimite date JSON?','res.json','req.json în orice rută','app.css'))
X('express-status','Coduri HTTP','200 indică succes, 400 o cerere invalidă, 403 interdicție, 404 resursă lipsă, iar 500 o eroare a serverului. Codul și mesajul sunt lucruri separate.', 'app.get("/missing", (req, res) => res.status(404).send("Not found"));',[dict(path='/missing',status=404,bodyExpected='Not found')],q('Ce cod indică resursa negăsită?','404','200','301 ca regulă generală'))
X('express-next','Lanț de middleware','Un middleware poate prelucra cererea și apela next pentru a continua. Dacă trimite răspunsul, de obicei nu continuă către încă un răspuns.', 'app.use((req, res, next) => { req.message = "Ready"; next(); });\napp.get("/hello", (req, res) => res.send(req.message));',[dict(path='/hello',bodyExpected='Ready')],q('Ce continuă la următorul handler?','next()','res.end urmat de next obligatoriu','req.start()'))
X('express-order','Ordinea înregistrării','Middleware-urile sunt evaluate în ordinea înregistrării. Un răspuns general pus prea devreme poate împiedica accesul la rutele de după el.', 'app.get("/hello", (req, res) => res.send("Hello"));\napp.use((req, res) => res.status(404).send("Not found"));',[dict(path='/hello',bodyExpected='Hello'),dict(path='/unknown',status=404,bodyExpected='Not found')],q('Unde pui fallback-ul 404?','După rutele cunoscute','Înaintea tuturor','În head'))
X('express-prefix','Middleware montat pe prefix','app.use("/admin", ...) se potrivește cu prefixul /admin și continuările sale de cale, nu cu orice șir care doar seamănă. Ruta GET are alte reguli de potrivire decât un prefix use.', 'app.use("/admin", (req, res, next) => { req.area = "Admin"; next(); });\napp.get("/admin/home", (req, res) => res.send(req.area));',[dict(path='/admin/home',bodyExpected='Admin')],q('Ce descrie app.use cu un prefix?','O zonă de căi','Doar un fișier cu extensie','Un selector CSS'))
X('express-params','Parametri în cale','Un segment :id este variabil și se citește din req.params.id. Valoarea este text; validează înainte să o folosești numeric sau într-o interogare.', 'app.get("/products/:id", (req, res) => res.send("Product " + req.params.id));',[dict(path='/products/7',bodyExpected='Product 7'),dict(path='/products/12',bodyExpected='Product 12')],q('Unde este id-ul unei rute /products/:id?','req.params.id','req.query.id obligatoriu','res.id'))
X('express-query','Parametri după ?','Query string este partea după ?. req.query oferă valorile parsate. Pentru exemple simple sunt texte; în situații generale verifică și tipul/forma, nu presupune că orice intrare este validă.', 'app.get("/search", (req, res) => res.send(String(req.query.q || "")));',[dict(path='/search?q=Cake',bodyExpected='Cake'),dict(path='/search',bodyExpected='')],q('Unde citești q din /search?q=Cake?','req.query.q','req.params.q','res.query.q'))
X('express-numbers','Conversie și validare la server','Datele trimise de client nu devin numere doar fiindcă arată numeric. Verifică prezența, forma, conversia și intervalul cerut.', 'app.get("/sum", (req, res) => {\n  const a = Number(req.query.a), b = Number(req.query.b);\n  if (typeof req.query.a !== "string" || typeof req.query.b !== "string" || !req.query.a.trim() || !req.query.b.trim() || !Number.isFinite(a) || !Number.isFinite(b)) { res.status(400).send("Invalid numbers"); return; }\n  res.send(String(a + b));\n});',[dict(path='/sum?a=5&b=7',bodyExpected='12'),dict(path='/sum?a=x&b=3',status=400,bodyExpected='Invalid numbers'),dict(path='/sum',status=400,bodyExpected='Invalid numbers')],q('Este Number("abc") un număr finit?','Nu','Da, 0','Da, 1'))
X('express-body','Date JSON din corpul cererii','express.json este un middleware care parsează corpul JSON și îl pune în req.body. El trebuie înregistrat înaintea handler-ului care citește body.', 'app.use(express.json());\napp.post("/message", (req, res) => res.json({ message: req.body.message }));',[dict(path='/message',method='POST',headers={'Content-Type':'application/json'},body='{"message":"Hello"}',json={'message':'Hello'})],q('Ce middleware parsează JSON-ul din corp?','express.json()','express.static()','path.json()'))
X('express-route','Grupează metodele unei căi','app.route("/items") permite legarea mai multor metode de aceeași cale. Lanțul nu execută toate metodele pentru o singură cerere.', 'app.route("/items").get((req, res) => res.send("List")).post((req, res) => res.status(201).send("Created"));',[dict(path='/items',bodyExpected='List'),dict(path='/items',method='POST',status=201,bodyExpected='Created')],q('Execută app.route toate metodele la orice cerere?','Nu; alege metoda potrivită','Da, în ordinea scrierii','Doar în GET'))
X('express-redirect','Redirecționează o adresă','res.redirect trimite un răspuns de redirecționare și destinația. Browserul poate face o cerere nouă spre acea destinație; nu este același lucru cu a randă template-ul în aceeași cerere.', 'app.get("/old", (req, res) => res.redirect("/new"));\napp.get("/new", (req, res) => res.send("New page"));',[dict(path='/old',bodyExpected='New page')],q('Ce face browserul de regulă după redirect?','Cere destinația','Compilează Sass','Șterge cookies obligatoriu'))
lesson(c,'express-static','Prefix URL și folder static','express.static mapează căile URL într-un folder. Prefixul montat este eliminat înainte de căutarea căii rămase. Nu adăuga de două ori același nume de director.',
 'app.use("/assets", express.static(path.join(__dirname, "public")));\n// URL /assets/css/site.css -> file public/css/site.css', 'Calea web /assets nu trebuie să fie și numele folderului de pe disc. În proiectul final fișierele statice au un prefix și o structură documentată.',q('Unde este fișierul pentru /assets/css/site.css?','public/css/site.css','public/assets/css/site.css','assets/public/css/site.css'),text('Scrie calea locală relativă pentru URL /assets/images/cake.svg.','public/images/cake.svg'))
lesson(c,'express-wildcard','Express 4 din slide-uri și Express 5 din proiect','Unele slide-uri folosesc wildcard-uri vechi precum /*. Proiectul local declară Express 5, unde wildcard-ul trebuie numit; forma /{*page} poate cuprinde și rădăcina. Nu copia automat sintaxa veche în altă versiune.',
 'app.get("/{*page}", (req, res) => {\n  res.status(404).send("Not found");\n});', 'Pentru fallback-ul simplu folosim app.use fără cale după rutele concrete. Astfel evităm să construim nume de template-uri direct din orice URL primit.',q('Ce verifici înainte de a copia o rută cu wildcard?','Versiunea Express și sintaxa acceptată','Doar culoarea editorului','Numele bazei SQL'),text('Scrie versiunea majoră folosită de proiectul de referință.','5'))
X('express-error','Tratarea unei erori','Un error handler Express are patru parametri: err, req, res, next. Nu arăta utilizatorului parole sau stack trace-uri interne; oferă un mesaj și păstrează detaliile pentru diagnostic local.', 'app.get("/broken", (req, res, next) => next(new Error("Training error")));\napp.use((err, req, res, next) => res.status(500).send("Server error"));',[dict(path='/broken',status=500,bodyExpected='Server error')],q('Câți parametri identifică un middleware de erori Express?','4','2','0'))
